                                    CredentialsMatchers.instanceOf(StandardUsernamePasswordCredentials.class)
                            ),
                            CredentialsProvider.lookupCredentials(StandardUsernamePasswordCredentials.class,
                                    context,
                                    ACL.SYSTEM,
                                    new ArrayList<DomainRequirement>())
                    );
        }

